394	// An end node's result is delivered to the caller verbatim for primitives
395	// (null, undefined, strings, numbers, booleans), but an object or array result
396	// must be structured-clonable: the engine snapshots it independently both at
397	// validation time and again when the end node actually runs. A function (or a
398	// symbol, getter-built object the clone algorithm rejects, etc.) nested in a
399	// result object/array is a definition error naming the end node and reason;
400	// bare function results cannot be delivered through JSON-style results either.
401	function compileEndResult(node) {
402	  if (!Object.hasOwn(node, 'result') || node.result === undefined) return;
403	  try {
404	    structuredClone(node.result);
405	  } catch {
406	    throw new Error(`end node ${node.id}: result must be a structured-cloneable value (objects and arrays must not contain functions)`);
407	  }
408	}
