410	// Resolves the outgoing edges of a node. Trigger, form and action nodes may
411	// name a single successor or a non-empty, duplicate-free array of successors;
412	// conditions keep their then/else pair and end nodes have none.
413	function normalizeSuccessors(node, nodes) {
414	  if (node.type === 'end') return [];
415	  if (node.type === 'condition') {
416	    for (const destination of [node.then, node.else]) {
417	      if (typeof destination !== 'string' || !nodes.has(destination)) {
418	        throw new Error(`node ${node.id} points to an unknown destination`);
419	      }
420	    }
421	    return [node.then, node.else];
422	  }
423	  const next = node.next;
424	  if (Array.isArray(next)) {
425	    if (next.length === 0) {
426	      throw new Error(`node ${node.id}: next array must not be empty`);
427	    }
428	    const seen = new Set();
429	    for (const destination of next) {
430	      if (typeof destination !== 'string') {
431	        throw new Error(`node ${node.id}: next array entries must be node id strings`);
432	      }
433	      if (seen.has(destination)) {
434	        throw new Error(`node ${node.id}: duplicate destination ${destination}`);
435	      }
436	      seen.add(destination);
437	      if (!nodes.has(destination)) {
438	        throw new Error(`node ${node.id} points to an unknown destination`);
439	      }
440	    }
441	    return [...seen];
442	  }
443	  if (typeof next !== 'string' || !nodes.has(next)) {
444	    throw new Error(`node ${node.id} points to an unknown destination`);
445	  }
446	  return [next];
447	}
