449	// Resolves the explicit dependencies of a node. Dependencies only gate when a
450	// node may run; they never activate it. A missing dependsOn means no
451	// dependencies, and the entry node must not declare any.
452	function normalizeDependencies(node, nodes, entryId) {
453	  if (!Object.hasOwn(node, 'dependsOn') || node.dependsOn === undefined) return [];
454	  if (!Array.isArray(node.dependsOn)) {
455	    throw new Error(`node ${node.id}: dependsOn must be an array`);
456	  }
457	  const seen = new Set();
458	  for (const dependency of node.dependsOn) {
459	    if (typeof dependency !== 'string') {
460	      throw new Error(`node ${node.id}: dependsOn entries must be node id strings`);
461	    }
462	    if (seen.has(dependency)) {
463	      throw new Error(`node ${node.id}: duplicate dependency ${dependency}`);
464	    }
465	    seen.add(dependency);
466	    if (!nodes.has(dependency)) {
467	      throw new Error(`node ${node.id} depends on an unknown node`);
468	    }
469	    if (dependency === node.id) {
470	      throw new Error(`node ${node.id} must not depend on itself`);
471	    }
472	  }
473	  const dependencies = [...seen];
474	  if (node.id === entryId && dependencies.length > 0) {
475	    throw new Error(`entry node ${node.id} must not declare dependencies`);
476	  }
477	  return dependencies;
478	}
