480	// Successor edges and dependency ordering constraints together must stay
481	// acyclic across the whole definition — including branches a run would never
482	// take and nodes the entry cannot reach. The error names a node id chain
483	// whose first and last entries match and whose steps are real edges or
484	// dependency relations.
485	//
486	// The search is an iterative three-color DFS with an explicit frame stack:
487	// a recursive walk over a legal definition tens of thousands of chained
488	// nodes deep would overflow the call stack before producing a result. `path`
489	// holds the gray nodes in DFS order (what a recursive stack would hold) and
490	// `depthById` locates a gray node in it, so a back edge still reports
491	// exactly the cycle segment — never the entry path leading into it.
492	function detectCycles(nodes) {
493	  const adjacency = new Map([...nodes.keys()].map(id => [id, []]));
494	  for (const [id, node] of nodes) {
495	    adjacency.get(id).push(...successorTargets.get(node));
496	    for (const dependency of nodeDependencies.get(node)) {
497	      adjacency.get(dependency).push(id);
498	    }
499	  }
500	  const color = new Map([...nodes.keys()].map(id => [id, 'white']));
501	
502	  for (const root of nodes.keys()) {
503	    if (color.get(root) !== 'white') continue;
504	    color.set(root, 'gray');
505	    const path = [root];
506	    const depthById = new Map([[root, 0]]);
507	    // Each frame is [node id, index of the next outgoing edge to examine].
508	    const frames = [[root, 0]];
509	    while (frames.length > 0) {
510	      const frame = frames[frames.length - 1];
511	      const id = frame[0];
512	      const edges = adjacency.get(id);
513	      if (frame[1] < edges.length) {
514	        const target = edges[frame[1]];
515	        frame[1] += 1;
516	        const targetColor = color.get(target);
517	        if (targetColor === 'gray') {
518	          const start = depthById.get(target);
519	          const chain = [...path.slice(start), target];
520	          throw new Error(`cycle is present: ${chain.join(' -> ')}`);
521	        }
522	        if (targetColor === 'white') {
523	          color.set(target, 'gray');
524	          depthById.set(target, path.length);
525	          path.push(target);
526	          frames.push([target, 0]);
527	        }
528	      } else {
529	        frames.pop();
530	        path.pop();
531	        depthById.delete(id);
532	        color.set(id, 'black');
533	      }
534	    }
535	  }
536	}
