1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync } from '../src/engine.js';
4	
5	// "__proto__" is a legal node identifier: the id is only ever matched as a
6	// whole string. A plain `output[id] = value` assignment for that id invokes the
7	// inherited Object.prototype.__proto__ setter instead of creating an own
8	// property, so these workflows pin the engine to storing every successful
9	// action result under its real node id regardless of spelling.
10	
11	// Builds an object that really owns a "__proto__" data property — an object
12	// literal with a quoted __proto__ key would hit the same JS setter and set the
13	// prototype instead.
14	function objectWithProtoKey(value) {
15	  const object = {};
16	  Object.defineProperty(object, '__proto__', {
17	    value, writable: true, enumerable: true, configurable: true,
18	  });
19	  return object;
20	}
21	
22	function protoActionWorkflow(actionNode, extraNodes = []) {
23	  return {
24	    id: 'special-id',
25	    entry: 'start',
26	    nodes: [
27	      { id: 'start', type: 'trigger', next: '__proto__' },
28	      { id: '__proto__', type: 'action', ...actionNode, next: 'check' },
29	      {
30	        id: 'check', type: 'condition',
31	        condition: { outputField: { nodeId: '__proto__' }, operator: 'eq', value: 'ok' },
32	        then: 'pass', else: 'fail',
33	      },
34	      { id: 'pass', type: 'end', result: 'passed' },
35	      { id: 'fail', type: 'end', result: 'failed' },
36	      ...extraNodes,
37	    ],
38	  };
39	}
40	
41	test('a __proto__ business action stores its result as an own enumerable property', async () => {
42	  const workflow = protoActionWorkflow({ operation: 'score' });
43	  const execution = await executeWorkflowAsync(workflow, {}, { score: () => 'ok' });
44	  assert.equal(execution.status, 'completed');
45	  assert.equal(execution.result, 'passed');
46	  assert.equal(Object.hasOwn(execution.context.output, '__proto__'), true);
47	  assert.deepEqual(Object.keys(execution.context.output), ['__proto__']);
48	  assert.deepEqual(execution.context.output, objectWithProtoKey('ok'));
49	  // The result survives JSON serialization under the real node id.
50	  assert.equal(JSON.stringify(execution.context.output), '{"__proto__":"ok"}');
51	});
52	
53	test('a __proto__ message action stores its result in both entries', async () => {
54	  const syncWorkflow = protoActionWorkflow({ message: 'ok' });
55	  const syncRun = executeWorkflow(syncWorkflow, {});
56	  assert.equal(syncRun.result, 'passed');
57	  assert.equal(Object.hasOwn(syncRun.context.output, '__proto__'), true);
58	  assert.equal(JSON.stringify(syncRun.context.output), '{"__proto__":"ok"}');
59	
60	  const asyncRun = await executeWorkflowAsync(syncWorkflow, {});
61	  assert.equal(asyncRun.result, 'passed');
62	  assert.equal(asyncRun.context.output['__proto__'], 'ok');
63	});
64	
65	test('inner fields of a __proto__ result belong only to that result', async () => {
66	  const workflow = protoActionWorkflow({ operation: 'score' });
67	  const execution = await executeWorkflowAsync(workflow, {}, { score: () => ({ score: 80 }) });
68	  assert.equal(execution.status, 'completed');
69	  assert.deepEqual(execution.context.output['__proto__'], { score: 80 });
70	  // The stored result never leaks into another node's slot or onto the store.
71	  assert.equal(execution.context.output.score, undefined);
72	  assert.equal(Object.getPrototypeOf(execution.context.output), Object.prototype);
73	  assert.deepEqual(Object.keys(execution.context.output), ['__proto__']);
74	});
75	
76	test('conditions read whole result, inner path and valueOutputField for a __proto__ node', async () => {
77	  const branchOf = async condition => {
78	    const workflow = {
79	      id: 'path-reads', entry: 'start',
80	      nodes: [
81	        { id: 'start', type: 'trigger', next: '__proto__' },
82	        { id: '__proto__', type: 'action', operation: 'score', next: 'other' },
83	        { id: 'other', type: 'action', operation: 'cap', next: 'check' },
84	        { id: 'check', type: 'condition', condition, then: 'pass', else: 'fail' },
85	        { id: 'pass', type: 'end', result: 'passed' },
86	        { id: 'fail', type: 'end', result: 'failed' },
87	      ],
88	    };
89	    const run = await executeWorkflowAsync(workflow, {}, {
90	      score: () => ({ score: 80 }),
91	      cap: () => ({ cap: 80 }),
92	    });
93	    return run.result;
94	  };
95	
96	  // The scenario from the report: score >= 80 takes the satisfied branch.
97	  assert.equal(
98	    await branchOf({ outputField: { nodeId: '__proto__', path: 'score' }, operator: 'gte', value: 80 }),
99	    'passed');
100	  assert.equal(
101	    await branchOf({ outputField: { nodeId: '__proto__', path: 'score' }, operator: 'gte', value: 81 }),
102	    'failed');
103	  // The whole result is comparable like any node's result.
104	  assert.equal(
105	    await branchOf({ outputField: { nodeId: '__proto__' }, operator: 'eq', value: 80 }),
106	    'failed');
107	  // The right-hand output reference works the same way.
108	  assert.equal(
109	    await branchOf({
110	      outputField: { nodeId: '__proto__', path: 'score' }, operator: 'gte',
111	      valueOutputField: { nodeId: 'other', path: 'cap' },
112	    }),
113	    'passed');
114	});
115	
116	test('a __proto__ node id is matched as a whole string; dots stay literal', async () => {
117	  const workflow = {
118	    id: 'dots-and-proto', entry: 'start',
119	    nodes: [
120	      { id: 'start', type: 'trigger', next: '__proto__.risk' },
121	      { id: '__proto__.risk', type: 'action', operation: 'score', next: 'check' },
122	      { id: 'check', type: 'condition', condition: {
123	        outputField: { nodeId: '__proto__.risk', path: 'score' }, operator: 'gte', value: 80,
124	      }, then: 'pass', else: 'fail' },
125	      { id: 'pass', type: 'end', result: 'passed' },
126	      { id: 'fail', type: 'end', result: 'failed' },
127	    ],
128	  };
129	  const run = await executeWorkflowAsync(workflow, {}, { score: () => ({ score: 80 }) });
130	  assert.equal(run.result, 'passed');
131	  assert.deepEqual(Object.keys(run.context.output), ['__proto__.risk']);
132	});
133	
134	test('saved null, empty string, 0, false and undefined count as present for a __proto__ node', async () => {
135	  for (const value of [null, '', 0, false, undefined]) {
